import React, { useState, useEffect } from "react";
import "./Preview.css";
import Navbar from "./Navbar";

function Preview({ data, updateData, onConfirm, onBack }) {

  const [editIncome, setEditIncome] = useState(false);

  // ✅ LOCAL FALLBACK STATE (MAIN FIX)
  const [localData, setLocalData] = useState({
    income: "",
    categories: [],
    limits: {}
  });

  const incomeOptions = [
    "Fixed Income",
    "Freelancer",
    "Business",
    "Multiple Income Sources"
  ];

  // ✅ LOAD FROM LOCALSTORAGE IF DATA MISSING
  useEffect(() => {
    if (data) return; // if props exist, no need

    const user = JSON.parse(localStorage.getItem("user"));
    if (!user) return;

    const income = localStorage.getItem(`income_${user.email}`);
    const categories = JSON.parse(localStorage.getItem(`categories_${user.email}`)) || [];
    const limits = JSON.parse(localStorage.getItem(`limits_${user.email}`)) || {};

    setLocalData({
      income,
      categories,
      limits
    });
  }, [data]);

  // ✅ USE EITHER PROPS OR LOCAL DATA
  const finalData = data || localData;

  // ✅ Update income
  const handleIncomeChange = (value) => {
    if (updateData) {
      updateData(prev => ({
        ...prev,
        income: value
      }));
    } else {
      setLocalData(prev => ({
        ...prev,
        income: value
      }));
    }
  };

  // ✅ Update limits
  const handleLimitChange = (category, value) => {
    if (updateData) {
      updateData(prev => ({
        ...prev,
        limits: {
          ...prev.limits,
          [category]: value
        }
      }));
    } else {
      setLocalData(prev => ({
        ...prev,
        limits: {
          ...prev.limits,
          [category]: value
        }
      }));
    }
  };

  return (
    <div className="preview-page">

      <Navbar title="Review Details" onBack={onBack} />

      <div className="preview-wrapper">

        <h1 className="preview-title">Review Your Setup</h1>
        <p className="preview-subtitle">
          Please confirm your details before proceeding
        </p>

        <div className="preview-card">

          {/* 🔹 INCOME */}
          <div className="preview-row">
            <div className="label">Income Type</div>

            <div className="value">
              {editIncome ? (
                <select
                  value={finalData.income || ""}
                  onChange={(e) => handleIncomeChange(e.target.value)}
                  className="preview-input"
                >
                  {incomeOptions.map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>
              ) : (
                finalData.income || "Not set"
              )}
            </div>

            <button onClick={() => setEditIncome(!editIncome)}>
              {editIncome ? "Save" : "Edit"}
            </button>
          </div>

          {/* 🔹 CATEGORIES */}
          <div className="preview-row">
            <div className="label">Selected Categories</div>
            <div className="value">
              {finalData.categories?.length > 0
                ? finalData.categories.join(", ")
                : "None Selected"}
            </div>
          </div>

          {/* 🔹 BUDGET LIMITS */}
          <div className="preview-row column">
            <div className="label">Budget Limits</div>

            {finalData.categories?.length > 0 ? (
              finalData.categories.map((cat) => (
                <div key={cat} className="limit-row">

                  <span className="limit-name">{cat}</span>

                  <input
                    type="number"
                    className="preview-input"
                    value={finalData.limits?.[cat] || ""}
                    onChange={(e) =>
                      handleLimitChange(cat, e.target.value)
                    }
                  />

                </div>
              ))
            ) : (
              <p>No categories selected</p>
            )}
          </div>

        </div>

        {/* 🔹 ACTIONS */}
        <div className="preview-actions">

          <button className="secondary-btn" onClick={onBack}>
            ← Back
          </button>

          <button className="primary-btn" onClick={onConfirm}>
            Continue to Dashboard
          </button>

        </div>

      </div>
    </div>
  );
}

export default Preview;
